import{_ as o,o as t,c as r,a0 as s}from"./chunks/framework.Czcffv53.js";const p=JSON.parse('{"title":"shared-agent-framework/http-channel routes","description":"","frontmatter":{"title":"shared-agent-framework/http-channel routes"},"headers":[],"relativePath":"reference/routes/http-channel.md","filePath":"reference/routes/http-channel.md"}'),n={name:"reference/routes/http-channel.md"};function a(i,e,d,c,h,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="shared-agent-framework-http-channel" tabindex="-1">shared-agent-framework/http-channel <a class="header-anchor" href="#shared-agent-framework-http-channel" aria-label="Permalink to &quot;shared-agent-framework/http-channel&quot;">​</a></h1><p>The HTTP routes this component serves: 2 on the Public server.</p><p><strong>Every path is relative.</strong> Each one is printed as the plugin declares it, under whatever prefix the component&#39;s constructor registers that plugin at. This page states no mount point, because the constructor is where the mount point is decided.</p><p>Generated from what the route plugins in <code>src/http-channel/routes.ts</code> declare, which is what a running Gateway serves at <code>GET /openapi.json</code>. Never edited by hand.</p><h2 id="public-server" tabindex="-1">Public server <a class="header-anchor" href="#public-server" aria-label="Permalink to &quot;Public server&quot;">​</a></h2><p><strong>The Public server is what a User&#39;s client calls.</strong> Which credential each route wants, and which wants none, is in that route&#39;s own description below.</p><h3 id="get" tabindex="-1"><code>GET /</code> <a class="header-anchor" href="#get" aria-label="Permalink to &quot;`GET /`&quot;">​</a></h3><p><strong>Read your own Message log</strong></p><p>The presented User&#39;s own Messages, both directions, in the single numbered sequence that is their log. There is <strong>no user parameter and nothing to omit</strong>. The log read is the one the Token names. No User can read another&#39;s by any spelling of the request. <code>?user=</code> is refused as the unknown parameter it is. <strong>Three cursor cases, one order.</strong> No cursor answers the newest page, which is what a client opening a conversation wants. <code>before=N</code> answers the newest page strictly below <code>N</code>, which is scrolling back. <code>after=N</code> walks forwards from <code>N</code>, which is polling, and <code>after=0</code> is how a log is read from its beginning, since nothing is numbered 0 and no cursor at all means the newest page instead. All three answer <strong>ascending by <code>seq</code></strong>, so a client concatenates pages without reversing anything. Passing <code>after</code> and <code>before</code> together is a <strong>400</strong>, because it describes two windows rather than one. The envelope carries <strong>no more-results flag</strong>, because a full page is one. <code>messages.length === limit</code> means there may be more. The next request is this one with the cursor moved on. <code>after</code> takes the largest <code>seq</code> received, to walk forwards. <code>before</code> takes the smallest, to walk back. A short page is the end of that direction for now. There is no read state of any kind (no stored position, no unread count and no receipts). So the cursor a client needs is one it already holds, because it is holding the Messages. <code>limit</code> defaults to 50 and is capped at 200. A larger value is <strong>refused with a 400</strong> rather than quietly reduced. The Messages past the cap are reachable by paging rather than lost. This is the one list in the framework with a cursor. A Message log is read by cursor and cannot be searched or filtered. The parameters are a window over one User&#39;s <code>seq</code>, and there is no full-text or field matching. <strong>Requires a bearer Token</strong>, presented as <code>Authorization: Bearer &lt;token&gt;</code> and obtained from <code>POST /auth/tokens</code>. The User acted on is the one the Gateway authenticated, and no parameter anywhere names another. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Messages</code>.</p><p><strong>Query parameters</strong></p><ul><li><p><strong><code>after</code></strong> <code>integer</code>, optional, 0 to 2147483647</p><p>Walk <strong>forwards</strong> from this <code>seq</code>, exclusive: the poll. <code>after=0</code> reads the log from its beginning, oldest first, which no other spelling expresses.</p></li><li><p><strong><code>before</code></strong> <code>integer</code>, optional, 0 to 2147483647</p><p>The newest page strictly <strong>below</strong> this <code>seq</code>: scrolling back. Answers ascending like every other case, so the page before the one in hand arrives the same way up.</p></li><li><p><strong><code>limit</code></strong> <code>integer</code>, optional, 1 to 200, default <code>50</code></p></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The window that matched, ascending by <code>seq</code>, with both directions interleaved as the one log they are.</p><ul><li><strong><code>messages</code></strong> array of <code>object</code>, required <ul><li><p><strong><code>id</code></strong> <code>string</code>, required</p></li><li><p><strong><code>userId</code></strong> <code>string</code>, required</p></li><li><p><strong><code>direction</code></strong> <code>string</code>, required, one of <code>&quot;inbound&quot;</code>, <code>&quot;outbound&quot;</code></p><p>Which way it travelled. <strong><code>inbound</code></strong> is the User to the agent and <strong><code>outbound</code></strong> is the agent to the User, and only a User can cause an inbound one. Decided by the server the request arrived on rather than by any field, so there is nothing anywhere for a caller to set.</p></li><li><p><strong><code>seq</code></strong> <code>integer</code>, required</p><p>This Message&#39;s number in <strong>one User&#39;s</strong> log, from 1, counting both directions. It is the cursor: the largest one held is what <code>after</code> takes to read whatever has arrived since. It is not global and no other User&#39;s activity moves it, so two Users&#39; Messages are not orderable against each other by it.</p></li><li><p><strong><code>text</code></strong> <code>string</code>, required</p></li><li><p><strong><code>createdAt</code></strong> <code>string</code>, required</p></li></ul></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>A cursor or <code>limit</code> is not an integer or is out of range, both cursors were passed, or a parameter this route does not take was written, <code>user</code> among them, since this route has none.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists. This part authenticates nobody: the refusal is <code>publicServer.requireUser</code>, taken as one option on the route, so it is the same 401 every protected route on this server answers, whichever scheme the deployment accepts.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="post" tabindex="-1"><code>POST /</code> <a class="header-anchor" href="#post" aria-label="Permalink to &quot;`POST /`&quot;">​</a></h3><p><strong>Submit a Message</strong></p><p>An <strong>inbound</strong> Message from the User the presented Token names. There is <strong>no field for the submitting User and nowhere for one to arrive</strong>. The id comes from the Token and from nothing a client can write, which is what makes the attribution trustworthy. A <code>userId</code> written into the body is stripped before the handler and reaches nothing. The Message and the Signal that wakes the agent for it are one transaction. A Message that was stored always has one. What the agent makes of it is <strong>not this response</strong>. An answer arrives on the log as an outbound Message whenever it arrives, which is what <code>after=&lt;seq&gt;</code> is for. <strong>Requires a bearer Token</strong>, presented as <code>Authorization: Bearer &lt;token&gt;</code> and obtained from <code>POST /auth/tokens</code>. The User acted on is the one the Gateway authenticated, and no parameter anywhere names another. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Messages</code>.</p><p><strong>Request body</strong></p><p><code>application/json</code>, required.</p><ul><li><strong><code>text</code></strong> <code>string</code>, required, at least 1 character</li></ul><p><strong>Responses</strong></p><p><strong><code>201</code></strong> <code>application/json</code></p><p>The Message as it was stored, including the <code>seq</code> it was given. That number is the cursor to poll from for the answer.</p><ul><li><p><strong><code>id</code></strong> <code>string</code>, required</p></li><li><p><strong><code>userId</code></strong> <code>string</code>, required</p></li><li><p><strong><code>direction</code></strong> <code>string</code>, required, one of <code>&quot;inbound&quot;</code>, <code>&quot;outbound&quot;</code></p><p>Which way it travelled. <strong><code>inbound</code></strong> is the User to the agent and <strong><code>outbound</code></strong> is the agent to the User, and only a User can cause an inbound one. Decided by the server the request arrived on rather than by any field, so there is nothing anywhere for a caller to set.</p></li><li><p><strong><code>seq</code></strong> <code>integer</code>, required</p><p>This Message&#39;s number in <strong>one User&#39;s</strong> log, from 1, counting both directions. It is the cursor: the largest one held is what <code>after</code> takes to read whatever has arrived since. It is not global and no other User&#39;s activity moves it, so two Users&#39; Messages are not orderable against each other by it.</p></li><li><p><strong><code>text</code></strong> <code>string</code>, required</p></li><li><p><strong><code>createdAt</code></strong> <code>string</code>, required</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p><code>text</code> is missing or empty, or a query parameter was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists. This part authenticates nobody: the refusal is <code>publicServer.requireUser</code>, taken as one option on the route, so it is the same 401 every protected route on this server answers, whichever scheme the deployment accepts.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>503</code></strong> <code>application/json</code></p><p>The Message <strong>was not recorded</strong>, and sending it again is the right thing to do. Nothing is wrong with the request and the log is intact: <code>seq</code> is computed per User inside the insert and a unique constraint makes a lost race visible, so this is one User&#39;s own concurrent writers outrunning a bounded retry. A 503 and not a 500 for that reason.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul>',42)])])}const u=o(n,[["render",a]]);export{p as __pageData,u as default};
